import React, { useState } from "react";
import { predict } from "../api";

// Example lists — replace with real model categories
const INDUSTRIES = [
  { label: "Technology", value: 0 },
  { label: "Finance", value: 1 },
  { label: "Healthcare", value: 2 },
  { label: "Retail", value: 3 }
];

const COUNTRIES = [
  { label: "USA", value: 0 },
  { label: "Kenya", value: 1 },
  { label: "India", value: 2 },
  { label: "Germany", value: 3 }
];

export default function Predict() {
  const [formData, setFormData] = useState({
    industry_enc: 0,
    country_enc: 0,
    company_age: 5,
    avg_size: 50,
    current_employee_estimate: 50,
    total_employee_estimate: 50,
    model_type: "rf_category"
  });

  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  // Update form values
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: Number(value) }));
  };

  // Submit prediction
  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setResult(null);

    try {
      const res = await predict(formData);
      setResult(res);

      // Auto-save successful prediction
      if (res && !res.error) saveToHistory(res);
    } catch (err) {
      setResult({ error: err.message || "API request failed" });
    }
    setLoading(false);
  };

  // Manual save function
  const saveToHistory = (res) => {
    const stored = JSON.parse(localStorage.getItem("predictionHistory") || "[]");
    stored.push({ ...formData, result: res });
    localStorage.setItem("predictionHistory", JSON.stringify(stored));
  };

  // Color code confidence
  const getConfidenceColor = (confidence) => {
    if (confidence == null) return "#000";
    if (confidence >= 0.75) return "green";
    if (confidence >= 0.5) return "orange";
    return "red";
  };

  return (
    <div style={{ padding: "20px", maxWidth: "700px", margin: "0 auto", fontFamily: "Arial, sans-serif" }}>
      <h1 style={{ textAlign: "center", color: "#333" }}>Company Growth Prediction</h1>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: "15px", marginTop: "20px" }}>
        {/* Industry */}
        <div>
          <label>Industry:</label>
          <select name="industry_enc" value={formData.industry_enc} onChange={handleChange} style={selectStyle}>
            {INDUSTRIES.map((i) => (
              <option key={i.value} value={i.value}>{i.label}</option>
            ))}
          </select>
        </div>

        {/* Country */}
        <div>
          <label>Country:</label>
          <select name="country_enc" value={formData.country_enc} onChange={handleChange} style={selectStyle}>
            {COUNTRIES.map((c) => (
              <option key={c.value} value={c.value}>{c.label}</option>
            ))}
          </select>
        </div>

        {/* Numeric fields */}
        {[
          { name: "company_age", label: "Company Age", min: 1, max: 50 },
          { name: "avg_size", label: "Average Company Size", min: 1, max: 1000 },
          { name: "current_employee_estimate", label: "Current Employee Estimate", min: 1, max: 1000 },
          { name: "total_employee_estimate", label: "Total Employee Estimate", min: 1, max: 5000 }
        ].map((field) => (
          <div key={field.name}>
            <label>{field.label}: {formData[field.name]}</label>
            <input
              type="range"
              name={field.name}
              min={field.min}
              max={field.max}
              value={formData[field.name]}
              onChange={handleChange}
              style={rangeStyle}
            />
          </div>
        ))}

        {/* Model Type */}
        <div>
          <label>Model Type:</label>
          <select name="model_type" value={formData.model_type} onChange={handleChange} style={selectStyle}>
            <option value="rf_category">RF Category</option>
            <option value="rf_level">RF Level</option>
            <option value="xgb_category">XGB Category</option>
            <option value="xgb_level">XGB Level</option>
          </select>
        </div>

        {/* Submit */}
        <button type="submit" disabled={loading} style={submitStyle}>
          {loading ? "Predicting..." : "Predict"}
        </button>
      </form>

      {/* Result */}
      {result && (
        <div style={resultCardStyle}>
          {result.error ? (
            <>
              <h3 style={{ color: "#f44336" }}>Error</h3>
              <p>{result.error}</p>
            </>
          ) : (
            <>
              <h3>Prediction Result</h3>
              <p><strong>Cluster:</strong> {result?.cluster ?? "-"}</p>
              <p><strong>Prediction:</strong> {result?.prediction ?? "-"}</p>
              <p>
                <strong>Confidence:</strong>{" "}
                <span style={{ color: getConfidenceColor(result?.confidence) }}>
                  {result?.confidence != null ? (result.confidence * 100).toFixed(2) + "%" : "-"}
                </span>
              </p>

              {/* Manual save button */}
              <button onClick={() => saveToHistory(result)} style={manualSaveStyle}>
                Save to History
              </button>
            </>
          )}
        </div>
      )}
    </div>
  );
}

// --- Styles ---
const selectStyle = {
  width: "100%",
  padding: "8px",
  borderRadius: "5px",
  border: "1px solid #ccc"
};

const rangeStyle = {
  width: "100%"
};

const submitStyle = {
  padding: "10px",
  fontSize: "16px",
  backgroundColor: "#4CAF50",
  color: "white",
  border: "none",
  borderRadius: "5px",
  cursor: "pointer",
  transition: "0.3s"
};

const resultCardStyle = {
  marginTop: "20px",
  padding: "15px",
  border: "1px solid #ccc",
  borderRadius: "5px",
  backgroundColor: "#f7f7f7"
};

const manualSaveStyle = {
  marginTop: "10px",
  padding: "8px 12px",
  fontSize: "14px",
  backgroundColor: "#2196F3",
  color: "white",
  border: "none",
  borderRadius: "5px",
  cursor: "pointer",
  transition: "0.3s"
};
